function microReportUI11(id){const o=microOffer11(id),a=microAuction11(id),e=state.prestige11.editions.find(e=>e.lot===id),ship=state.shipments.find(s=>s.source5?.microlot===id),source=microSource11(o),rowsMade=state.craft5.ledger.filter(r=>r.sources.some(s=>s.source.microlot===id));prestigeShell11(o.name,`<span class="badge">${a?microStatusLabel11(a):state.week<o.closes?'Otevřená aukce':'Uzavřená aukce'}</span><p>${esc(o.producer)} · ${esc(ORIGINS[o.origin].name)} · sklizeň T${o.opens}</p>${rows([['Konečné množství',o.kg+' kg'],['Odrůda / zpracování',VARIETIES5[o.variety].name+' / '+PROCESSES5[o.process].name],['Fermentace',o.hours+' hodin'],['Kvalita zelených zrn',o.quality+'/100'],['Uzavření aukce','Po odehrání T'+o.closes],['Cena celé partie',money(a?.price||o.minimum)],['Doprava',money(o.shipping)],['Záloha nyní',money(a?.escrow||0)],['Kapacita zeleného skladu',number(microGreenCapacity11(),0)+' kg'],['Dostupná zelená káva',number(microAmount11(id),1)+' kg'],['Spotřebováno do pražení',number(a?.used||0,1)+' kg'],['Zásilka',ship?'Příjezd T'+ship.due:a?.received?'Doručeno T'+a.received:'Zatím bez vlastní dodávky']])}${flavorBars5(source.flavor)}<div class="prestige-actions11">${state.week>=o.opens&&state.week<o.closes?`<button class="primary" id="microBid11">Připravit příhoz</button>`:''}${a?.leader==='player'&&['received','transit'].includes(a.status)&&!e?'<button class="primary" id="microEdition11">Připravit limitovanou edici</button>':''}${e?`<button class="primary" id="microRoast11">Pražit ${esc(blend(e.blend).name)}</button>`:''}<button class="soft" id="prestigeBack11">Všechny partie a soutěže</button></div>${e?'<p class="sub">Edice používá pouze tuto partii. Nové pražení se při vyčerpání zastaví; hotové šarže se dál prodávají přes běžné dodávky, kavárny a balení.</p>':''}${rowsMade.length?`<details><summary>Vyrobené šarže · poslední dochovaná evidence</summary>${rowsMade.map(r=>`<p>T${r.week} · ${esc(r.recipe.name)} · ${number(r.output,1)} kg · <button class="soft" data-craft-trace="${r.id}">Cesta šarže</button></p>`).join('')}</details>`:''}${a?`<details><summary>Neměnná historie příhozů a vrácených záloh</summary><div class="table-scroll" tabindex="0"><table><thead><tr><th>Týden</th><th>Kdo</th><th>Cena celé partie</th></tr></thead><tbody>${a.bids.map(b=>`<tr><td>${b.week}</td><td>${b.actor==='player'?'Tvoje firma':esc(state.rivals.find(r=>r.id===b.actor).name)}</td><td>${money(b.amount)}</td></tr>`).join('')}</tbody></table></div>${a.refunds.map(r=>`<p>T${r.week} · ${r.actor==='player'?'Tvoje firma':esc(state.rivals.find(x=>x.id===r.actor).name)} · vráceno ${money(r.amount)}</p>`).join('')}</details>`:''}`);el('prestigeBack11').onclick=prestigeHome11;if(el('microBid11'))el('microBid11').onclick=()=>microBidUI11(id);if(el('microEdition11'))el('microEdition11').onclick=()=>microEditionUI11(id);if(el('microRoast11'))el('microRoast11').onclick=()=>{craftBlend5=e.blend;el('modal').close();goto('craft');};document.querySelectorAll('[data-craft-trace]').forEach(b=>b.onclick=()=>craftTraceDialog5(b.dataset.craftTrace));}
function microBidUI11(id){const o=microOffer11(id),a=microAuction11(id);prestigeShell11('Příhoz · '+o.name,`<p>Cena je za celou partii ${o.kg} kg. Záloha zahrnuje ${money(o.shipping)} dopravy; při předběhnutí se vrátí. Vyhranou partii nelze zrušit.</p><div class="fields">${field('Cena celé partie / Kč',input('microAmount11',microNextBid11(o,a),microNextBid11(o,a),o.minimum*5,1000))}${field('Chráněná rezerva / týdny',input('microReserve11',3,1,8))}</div><button class="primary" id="microQuote11">Prověřit příhoz</button>`);el('microQuote11').onclick=()=>{try{const amount=Number(el('microAmount11').value),reserve=Number(el('microReserve11').value),q=microBidQuote11(id,amount,reserve);prestigeShell11('Potvrzení příhozu',rows([['Cena partie',money(q.amount)],['Doprava',money(q.shipping)],['Celá záloha',money(q.total)],['Nová platba nyní',money(q.cost)],['Hotovost po platbě',money(state.cash-q.cost)],['Chráněná rezerva',money(q.protectedCash)]])+`<p>Soupeři mohou přihodit v dalších týdnech. Aukce se uzavře v T${o.closes}.</p><button class="primary" id="microApprove11" ${q.safe?'':'disabled'}>Rezervovat ${money(q.cost)}</button>`);el('microApprove11').onclick=()=>acquisitionConfirmUI9('Potvrdit příhoz?',money(q.cost)+' se nyní rezervuje z hotovosti.',()=>bidMicro11(id,amount,reserve,q),'Potvrdit příhoz',()=>microReportUI11(id));}catch(e){toast(e.message);}};}
function microEditionUI11(id){const o=microOffer11(id);prestigeShell11('Limitovaná edice',`<p>Receptura stojí 15 000 Kč. Neobsahuje novou kávu ani pražení; využije pouze zaplacenou partii ${esc(o.name)}.</p><div class="fields">${field('Název kávy','<input id="editionName11" maxlength="40" value="'+esc(o.name)+'">')}${field('Pražení','<select id="editionRoast11"><option value="1">Světlé</option><option value="2">Střední</option><option value="3">Tmavé</option></select>')}${field('Obal','<select id="editionPack11"><option value="premium">Výběrový</option><option value="classic">Klasický</option><option value="eco">Ekologický</option></select>')}${field('Referenční cena / Kč za kg',input('editionPrice11',1000,250,1200))}${field('Chráněná rezerva / týdny',input('editionReserve11',3,1,8))}</div><button class="primary" id="editionQuote11">Prověřit edici</button>`);el('editionQuote11').onclick=()=>{try{const d={name:el('editionName11').value,roast:Number(el('editionRoast11').value),packaging:el('editionPack11').value,price:Number(el('editionPrice11').value)},reserve=Number(el('editionReserve11').value),q=microEditionQuote11(id,d,reserve);if(!q.safe)return toast('Edice by porušila chráněnou rezervu.');acquisitionConfirmUI9('Uvést limitovanou recepturu?',esc(q.data.name)+' · 15 000 Kč. Zásobu vytvoří až skutečné pražení.',()=>createMicroEdition11(id,d,reserve,q),'Zaplatit recepturu',()=>microReportUI11(id));}catch(e){toast(e.message);}};}
function contestNewUI11(blendId=null){const lots=prestigeLots11(blendId);if(!lots.length){prestigeShell11('Nejdřív vyrob soutěžní kávu','<p>Potřebuješ alespoň 500 g obchodní šarže ze své pražírny, staré nejvýše čtyři týdny. Autentická šarže má vlastní pražicí profil nebo dohledatelnou odrůdu a zpracování sklizně. Dodavatelská hotová káva a laboratorní zásoba se nepřihlašují.</p><button class="primary" id="contestCraft11">Přejít k pražení</button><button class="soft" id="prestigeBack11">Přehled prestiže</button>');el('contestCraft11').onclick=()=>{el('modal').close();goto('craft');};el('prestigeBack11').onclick=prestigeHome11;return;}prestigeShell11('Přihlásit skutečnou šarži',`<p>Porota dostane 500 g vybrané kávy; vzorek se hned odebere ze skladu. Vstupné 18 000 Kč je nevratné.</p><div class="fields">${field('Fyzická šarže','<select id="contestLot11">'+lots.map(l=>option(l.id,l.craft5.recipe.name+' · '+l.zone+' · T'+l.roastedWeek+' · '+number(l.kg,1)+' kg',lots[0].id)).join('')+'</select>')}${field('Kategorie','<select id="contestCategory11">'+Object.entries(COFFEE_CONTESTS11).map(([k,c])=>option(k,c.name,'filter')).join('')+'</select>')}${field('Chráněná rezerva / týdny',input('contestReserve11',3,1,8))}</div><p class="sub">Kvalita tvoří 60 % skóre, shoda chuti s kategorií 30 % a čerstvost 10 %. Porota uchová skutečný vzorek i tehdejší soupeře.</p><p id="contestAvailability11" role="status"></p><button class="primary" id="contestQuote11">Prověřit přihlášku</button>`);contestAvailabilityUI11();el('contestLot11').onchange=contestAvailabilityUI11;el('contestCategory11').onchange=contestAvailabilityUI11;el('contestQuote11').onclick=()=>{try{const batch=el('contestLot11').value,category=el('contestCategory11').value,reserve=Number(el('contestReserve11').value),q=contestQuote11(batch,category,reserve);prestigeShell11('Potvrzení soutěžního vzorku',rows([['Káva',q.sample.craft.recipe.name],['Šarže',q.batch],['Odebere se','500 g'],['Datum pražení','T'+q.sample.roasted],['Stáří',q.sample.age+' týdnů'],['Účetní náklad vzorku',money(q.cost)],['Vstupné nyní',money(q.fee)],['Hotovost po platbě',money(state.cash-q.fee)],['Chráněná rezerva',money(q.protectedCash)]])+`<p>Vyhodnocení v T${state.week+2}. Medaile není zaručená. Staré šarže a jiné původy nepřevezmou ocenění zdarma.</p><button class="primary" id="contestApprove11" ${q.safe?'':'disabled'}>Odeslat vzorek a zaplatit</button>`);el('contestApprove11').onclick=()=>{let entry;acquisitionConfirmUI9('Zaplatit soutěž a odeslat vzorek?','18 000 Kč nyní a 500 g skutečné kávy ze skladu.',()=>entry=enterContest11(batch,category,reserve,q),'Zaplatit a odeslat',()=>contestReportUI11(entry.id));};}catch(e){toast(e.message);}};}
function contestAvailabilityUI11(){const lot=prestigeLots11().find(l=>l.id===el('contestLot11').value),category=el('contestCategory11').value,last=lot&&state.prestige11.entries.find(e=>e.sample.blend===lot.blend&&e.category===category&&state.week-e.entered<26);el('contestQuote11').disabled=!!last;el('contestAvailability11').textContent=last?'Tato káva už má přihlášku do kategorie '+COFFEE_CONTESTS11[category].name+'. Další přihláška od T'+(last.entered+26)+'. Můžeš zvolit jinou kategorii.':'';}
function contestReportUI11(id){const e=state.prestige11.entries.find(e=>e.id===id),s=e.sample,effect=prestigeEffect11(s.blend,s.city);prestigeShell11(COFFEE_CONTESTS11[e.category].name+' · '+s.craft.recipe.name,`<span class="badge">${e.status==='judging'?'Porota hodnotí · T'+e.due:CONTEST_AWARDS11[e.award]}</span>${rows([['Vzorek',number(s.kg,1)+' kg · '+s.batch],['Pražení','T'+s.roasted+' · '+s.craft.roaster.name],['Stáří při přihlášení',s.age+' '+(s.age===1?'týden':s.age>=2&&s.age<=4?'týdny':'týdnů')],['Vstupné',money(e.fee)],['Spotřebovaná zásoba',money(e.cost)]])}<details><summary>Původ skutečného odeslaného vzorku</summary>${s.craft.sources.map(p=>`<p>${esc(sourceLabel5(p.source))} · ${number(p.kg/s.craft.input*100,1)} %</p>`).join('')}${flavorBars5(s.craft.flavor)}</details>${e.status==='completed'?`<h3>Výsledek poroty</h3>${rows([['Kvalita · váha 60 %',number(e.judges.quality,2)+'/100'],['Chuť · váha 30 %',number(e.judges.taste,2)+'/100'],['Čerstvost · váha 10 %',e.judges.freshness+'/100'],['Celkové skóre',number(e.judges.score,2)+'/100'],['Pořadí',e.rank+'. z '+(e.field.length+1)],['Ocenění',CONTEST_AWARDS11[e.award]],['Platnost přínosu','Do T'+e.expires],['Nynější přínos v '+s.city,'+'+number((effect.demand-1)*100,1)+' % poptávky'],['Důvěra v tuto kávu','+'+number(effect.trust,1)+' / 100']])}<p class="sub">Přínos má strop 8 % poptávky a 4 body důvěry. Platí pouze při dostupné kávě se stejnou recepturou, profilem a původem; slábne se stářím. Ocenění se nesčítají a nemění trvale pověst celé firmy.</p><details><summary>Doboví soupeři</summary>${e.field.map(r=>`<p>${esc(r.name)} · ${r.score}/100</p>`).join('')}</details>`:'<p>Výsledek přijde při vyhodnocení T'+e.due+'. Původ, chuť, stáří a soupeři přihlášky se už nemění.</p>'}<button class="soft" id="prestigeBack11">Partie a soutěže</button>`);el('prestigeBack11').onclick=prestigeHome11;}
function prestigeBind11(){document.querySelectorAll('[data-prestige11]').forEach(b=>b.onclick=prestigeHome11);document.querySelectorAll('[data-micro-report11]').forEach(b=>b.onclick=()=>microReportUI11(b.dataset.microReport11));document.querySelectorAll('[data-contest-report11]').forEach(b=>b.onclick=()=>contestReportUI11(b.dataset.contestReport11));document.querySelectorAll('[data-edit-blend]').forEach(b=>{const e=microEdition11(b.dataset.editBlend);if(e){b.textContent='Limitovaná edice a původ';b.onclick=()=>microReportUI11(e.lot);}});document.querySelectorAll('[data-competition]').forEach(b=>{b.disabled=false;b.onclick=()=>contestNewUI11(b.dataset.competition);});}
